// ===== CONFIG — edite os valores abaixo antes de ativar o workflow =====
// (mesmos valores do workflow A — mantenha os dois sincronizados)
return [{
  json: {
    clickupBaseUrl: "https://api.clickup.com/api/v2",
    clickupListId: "901321051391",

    fieldTarefasSkill: "036acdcf-df5a-4a6f-a944-3845236cd64a",
    valorSkillCaptacao: "5f1d6dd8-7738-4754-a0b9-a033b8be380b",
    fieldNomeCaptado: "5eac4259-559b-4faa-bae0-b5d544a1a040",
    fieldTelefoneCaptado: "ec822183-eb29-4434-9dd3-4c36276135ea",

    uazapiBaseUrl: "https://SEU-DOMINIO.uazapi.com",

    telefoneThiago: "PREENCHER_55DDNNNNNNNNN",
    telefoneMariaClara: "PREENCHER_55DDNNNNNNNNN",

    googleSheetsSpreadsheetId: "1tYkmBMk2A6Gpw6rJtCpT_bQeC-k2X1QtNVivJf0VkmU",
    googleSheetsLogTab: "Log"
  }
}];

// Extrai remetente e texto do payload da UAZAPI de forma defensiva — o formato exato
// só dá pra confirmar com um payload real chegando (rode 1x e confira em $json.body
// com "Listen for test event"; ajuste os caminhos abaixo se vierem diferentes).
const item = $input.first().json;
const payload = item.body ?? item;
const msg = payload.message || payload.data || payload;

const texto = (
  msg.text ??
  msg.body ??
  msg?.message?.conversation ??
  msg?.content ??
  ''
).toString().trim();

const remetenteBruto = (
  msg.sender ??
  msg.from ??
  msg.chatid ??
  msg.number ??
  payload.chatid ??
  ''
).toString();
const remetente = remetenteBruto.replace(/\D/g, '');

const fromMe = Boolean(msg.fromMe ?? payload.fromMe ?? false);
const wasSentByApi = Boolean(msg.wasSentByApi ?? payload.wasSentByApi ?? false);

const textoNormalizado = texto.toLowerCase();
const ehComandoAdiar = textoNormalizado === 'adiar captação' || textoNormalizado === 'adiar captacao';

return [{
  json: {
    texto,
    remetente,
    ehComandoAdiar,
    ignorar: fromMe || wasSentByApi || !texto || !remetente,
  }
}];

const config = $('CONFIG').first().json;
const remetente = $('Normalizar Mensagem').first().json.remetente;
const tasks = ($input.first().json.tasks) || [];
const nowMs = Date.now();
const MESES = ['JAN','FEV','MAR','ABR','MAI','JUN','JUL','AGO','SET','OUT','NOV','DEZ'];

function parseDescField(desc, label) {
  const re = new RegExp('^' + label + ':\\s*(.+)$', 'm');
  const m = (desc || '').match(re);
  return m ? m[1].trim() : '';
}
function getCF(task, fieldId) {
  if (!fieldId) return null;
  const cf = (task.custom_fields || []).find(f => f.id === fieldId);
  return cf ? cf.value : null;
}

// A busca no ClickUp já filtra pelo campo "WhatsApp do captado" = remetente; pegamos a
// próxima captação (a mais próxima no tempo) que ainda não terminou há mais de 1h.
const candidatos = tasks
  .filter(t => t.start_date && Number(t.start_date) > nowMs - 60 * 60 * 1000)
  .sort((a, b) => Number(a.start_date) - Number(b.start_date));

const task = candidatos[0];

if (!task) {
  return [{
    json: {
      naoEncontrado: true,
      remetente,
      respostaCaptado: 'Não encontrei nenhuma captação sua marcada pra frente. Fala direto com a gente pra resolver.',
      avisos: [],
      comentarioClickUp: '',
      taskId: null,
    }
  }];
}

const startMs = Number(task.start_date);
const diffMin = (startMs - nowMs) / 60000;
const dentroPrazo = diffMin >= 60;

const marcaMatch = (task.name || '').match(/^\[CAPTAÇÃO\]\s*([^-]+?)\s*-/);
const marca = marcaMatch ? marcaMatch[1].trim() : '';
const desc = task.text_content || task.description || '';
const solicitanteNome = parseDescField(desc, 'Solicitante') || 'o solicitante';
const solicitanteTel = parseDescField(desc, 'WhatsApp do solicitante').replace(/\D/g, '');
const nomeCaptado = (getCF(task, config.fieldNomeCaptado) || '').toString().trim() || 'a pessoa captada';

const shifted = new Date(startMs - 3 * 60 * 60 * 1000);
const dataFmt = `${String(shifted.getUTCDate()).padStart(2, '0')} ${MESES[shifted.getUTCMonth()]}`;
const horaFmt = `${String(shifted.getUTCHours()).padStart(2, '0')}:${String(shifted.getUTCMinutes()).padStart(2, '0')}`;

let respostaCaptado;
let comentarioClickUp;
let textoAviso;

if (dentroPrazo) {
  respostaCaptado = 'Tudo bem, vamos remarcar. Consegue sugerir uma nova data e horário para a captação? Precisa ser dentro dos próximos 7 dias, a partir de hoje.';
  comentarioClickUp = `Pedido de adiamento (dentro do prazo) recebido via WhatsApp de ${nomeCaptado}. Aguardando sugestão de nova data (prazo: 7 dias a partir de hoje). Revisar manualmente.`;
  textoAviso = `A captação de ${marca} (${dataFmt} ${horaFmt}) foi adiada por ${nomeCaptado}. Aguardando sugestão de nova data (prazo de 7 dias).`;
} else {
  respostaCaptado = `Esse horário já está muito próximo (menos de 1h) para adiar por aqui. Fala direto com ${solicitanteNome} ou comigo pra resolver.`;
  comentarioClickUp = `🚨 Pedido de adiamento EM CIMA DA HORA (menos de 1h) via WhatsApp de ${nomeCaptado}. Recusado automaticamente — precisa de contato manual.`;
  textoAviso = `🚨 ${nomeCaptado} pediu pra adiar a captação de ${marca} (${dataFmt} ${horaFmt}) em cima da hora (menos de 1h). Precisa de atenção manual.`;
}

const avisos = [
  { telefone: config.telefoneThiago, texto: textoAviso },
  { telefone: config.telefoneMariaClara, texto: textoAviso },
];
if (solicitanteTel) {
  avisos.push({ telefone: solicitanteTel, texto: textoAviso });
}
// se a task não tiver "WhatsApp do solicitante" preenchido, ele simplesmente não recebe
// o aviso automático — Thiago e Maria recebem sempre.

return [{
  json: {
    naoEncontrado: false,
    taskId: task.id,
    dentroPrazo,
    remetente,
    respostaCaptado,
    comentarioClickUp,
    avisos,
  }
}];
